'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var objectKeys = require( '@stdlib/utils/keys' );
var objectValues = require( '@stdlib/utils/values' );
var existsSync = require( '@stdlib/fs/exists' ).sync;
var rootDir = require( '@stdlib/_tools/utils/root-dir' );
var FUNCTION_DATABASE = require( '@stdlib/math/special/data/unary_function_database.json' );


// VARIABLES //

var ROOT_DIR = resolve( rootDir(), 'lib', 'node_modules' );


// FUNCTIONS //

/**
* Returns an array of unique values.
*
* @private
* @param {Array} arr - input array
* @returns {Array} array of unique values
*/
function unique( arr ) {
	var obj;
	var i;
	obj = {};
	for ( i = 0; i < arr.length; i++ ) {
		obj[ arr[i] ] = true;
	}
	return objectKeys( obj );
}


// MAIN //

/**
* Checks whether all scalar kernels for a given function have C implementations.
*
* @private
* @param {string} funcName - function name
* @returns {boolean} boolean indicating whether all scalar kernels have C implementations
*
* @example
* var bool = hasCImplementation( 'acosd' );
* // returns true
*/
function hasCImplementation( funcName ) {
	var kernelPaths;
	var kernelPath;
	var funcData;
	var pkgJson;
	var pkgPath;
	var i;

	funcData = FUNCTION_DATABASE[ funcName ];

	/*
	* For example, if funcName = 'asecd', then
	*
	* funcData = {
	*     "input_dtypes": "real_and_generic",
	*     "output_dtypes": "real_floating_point_and_generic",
	*     "excluded_dtypes": [
	*         "float16",
	*         "uint8c",
	*         "int64",
	*         "uint64"
	*     ],
	*     "primary_dtype": "float64",
	*     "scalar_kernels": {
	*         "float32": "@stdlib/math/base/special/asecdf",
	*         "float64": "@stdlib/math/base/special/asecd",
	*         "generic": "@stdlib/math/base/special/asecd"
	*     },
	*     "policies": {
	*         "output": "real_floating_point_and_generic",
	*         "casting": "none"
	*     }
	* }
	*/
	if ( !funcData || !funcData.scalar_kernels ) {
		return false;
	}

	kernelPaths = unique( objectValues( funcData.scalar_kernels ) );

	/*
	* For example, if funcName = 'asecd', then
	*
	* kernelPaths = [
	*     "@stdlib/math/base/special/asecdf",
	*     "@stdlib/math/base/special/asecd"
	* ]
	*/
	for ( i = 0; i < kernelPaths.length; i++ ) {
		kernelPath = kernelPaths[ i ];
		pkgPath = resolve( ROOT_DIR, kernelPath, 'package.json' );

		if ( !existsSync( pkgPath ) ) {
			return false;
		}
		pkgJson = require( pkgPath ); // eslint-disable-line stdlib/no-dynamic-require
		if ( !pkgJson.directories || !pkgJson.directories.src ) {
			return false;
		}
	}
	return true;
}


// EXPORTS //

module.exports = hasCImplementation;
